CREATE TABLE IF NOT EXISTS subcontract_payments(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,payment_code VARCHAR(30) NOT NULL,subcontract_id BIGINT UNSIGNED NOT NULL,vendor_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(18,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,reference_number VARCHAR(190) NULL,approved_progress_percentage_snapshot DECIMAL(7,4) NULL,approved_earned_value_snapshot DECIMAL(18,2) NULL,previous_payments_snapshot DECIMAL(18,2) NULL,available_payment_snapshot DECIMAL(18,2) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,posted_at DATETIME NULL,posted_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_subcontract_payments_code(payment_code),KEY idx_subcontract_payments_history(subcontract_id,payment_date,id),KEY idx_subcontract_payments_filters(status,payment_method,payment_date),CONSTRAINT fk_subcontract_payments_subcontract FOREIGN KEY(subcontract_id) REFERENCES subcontracts(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_payments_vendor FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_payments_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_payments_created_by FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_payments_posted_by FOREIGN KEY(posted_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_payments_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontract_payments_amount CHECK(amount>0),CONSTRAINT chk_subcontract_payments_method CHECK(payment_method IN('cash','bank_transfer','cheque','other')),CONSTRAINT chk_subcontract_payments_status CHECK(status IN('draft','posted','cancelled')),CONSTRAINT chk_subcontract_payments_snapshots CHECK((approved_progress_percentage_snapshot IS NULL OR approved_progress_percentage_snapshot>=0)AND(approved_earned_value_snapshot IS NULL OR approved_earned_value_snapshot>=0)AND(previous_payments_snapshot IS NULL OR previous_payments_snapshot>=0)AND(available_payment_snapshot IS NULL OR available_payment_snapshot>=0)),CONSTRAINT chk_subcontract_payments_posted CHECK(status<>'posted' OR(posted_at IS NOT NULL AND posted_by IS NOT NULL AND approved_progress_percentage_snapshot IS NOT NULL AND approved_earned_value_snapshot IS NOT NULL AND previous_payments_snapshot IS NOT NULL AND available_payment_snapshot IS NOT NULL)),CONSTRAINT chk_subcontract_payments_cancelled CHECK(status<>'cancelled' OR(cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
